Index: index.html
===================================================================
--- index.html
+++ index.html
@@ -20,4 +20,51 @@
 </div>
 <div class="modal" id="modal"><div class="card"><i class="corner c1"></i><i class="corner c2"></i><div class="eyebrow" id="modalKicker">A city holds its breath</div><h1 id="modalTitle">The Veil of <span>Greyhaven</span></h1><p class="subtitle" id="modalSubtitle">A stealth tale in the drowned quarter</p><p class="story" id="modalStory">The Lord Regent has sealed the old harbor. Three brass seals open the way into his watchtower — and the truth buried beneath it. Keep to the shadows. The city has a long memory.</p><div class="mission" id="mission"><span class="seal">◈</span><span>Recover <em>three brass seals</em> and reach the lighthouse extraction. Stay unseen, or break the watch with your shadow-step.</span></div><button class="button" id="play">Enter the quarter&nbsp; →</button><span class="smallnote">WASD to move · Shift to creep · Space to blink</span><div class="footer"><span>GREYHAVEN · 1842</span><span>NO ONE IS BORN INNOCENT</span></div></div></div>
 </main>
 <script>
+(()=>{
+const canvas=document.querySelector('#scene'),ctx=canvas.getContext('2d'),game=document.querySelector('#game');
+const W=1280,H=800,WW=1800,WH=1300;
+let dpr=1,scale=1,cam={x:0,y:0},last=0,running=false,won=false,gameOver=false,time=0,toastTimer=0;
+const ui={modal:document.querySelector('#modal'),play:document.querySelector('#play'),title:document.querySelector('#modalTitle'),kicker:document.querySelector('#modalKicker'),subtitle:document.querySelector('#modalSubtitle'),story:document.querySelector('#modalStory'),mission:document.querySelector('#mission'),objective:document.querySelector('#objective'),seals:document.querySelector('#sealCount'),health:document.querySelector('#healthFill'),healthNum:document.querySelector('#healthNum'),blink:document.querySelector('#blinkFill'),blinkNum:document.querySelector('#blinkNum'),alert:document.querySelector('#alert'),toast:document.querySelector('#toast')};
+function resize(){const r=game.getBoundingClientRect();dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(r.width*dpr);canvas.height=Math.round(r.height*dpr);scale=Math.min(canvas.width/W,canvas.height/H);}
+new ResizeObserver(resize).observe(game);resize();
+const keys={},mouse={x:W*.5,y:H*.5,down:false};
+addEventListener('keydown',e=>{const k=e.key.toLowerCase();keys[k]=true;if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();if(k===' '&&!e.repeat&&running)blink();if(k==='e'&&!e.repeat&&running)interact();if(k==='q'&&!e.repeat&&running)whistle();if(k==='enter'&&!running)startGame();});
+addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
+canvas.addEventListener('pointermove',e=>{const r=canvas.getBoundingClientRect();mouse.x=(e.clientX-r.left)*W/r.width;mouse.y=(e.clientY-r.top)*H/r.height;});
+canvas.addEventListener('pointerdown',()=>{mouse.down=true});addEventListener('pointerup',()=>mouse.down=false);
+const player={x:135,y:1090,angle:-.4,hp:100,blink:0,blinkMax:4.2,has:0,hidden:false,invuln:0};
+const seals=[{x:470,y:1080,got:false},{x:865,y:650,got:false},{x:1440,y:342,got:false}];
+const exit={x:1655,y:180};
+const buildings=[
+ {x:210,y:420,w:245,h:205,name:'THE SALT HOUSE',roof:'#353d39'},
+ {x:540,y:390,w:300,h:230,name:'OLD CUSTOMS',roof:'#3b403a'},
+ {x:920,y:260,w:230,h:190,name:'THE ABBEY',roof:'#373c37'},
+ {x:280,y:790,w:300,h:180,name:'FISHMONGER ROW',roof:'#3d423b'},
+ {x:650,y:900,w:260,h:230,name:'THE GULL',roof:'#343a36'},
+ {x:1020,y:760,w:300,h:210,name:'DOCK OFFICE',roof:'#3b403b'},
+ {x:1320,y:460,w:260,h:230,name:'WATCH HOUSE',roof:'#373c38'},
+ {x:1410,y:80,w:240,h:170,name:'LIGHTHOUSE KEEP',roof:'#42443d'}
+];
+const solid=buildings.map(b=>({x:b.x,y:b.y,w:b.w,h:b.h}));
+const guards=[
+ {x:440,y:720,route:[[440,720],[650,710],[675,820],[460,845]],i:0,dir:0,state:'patrol',alert:0,stun:0,speed:45},
+ {x:840,y:335,route:[[850,340],[870,590],[1000,645],[1165,610]],i:0,dir:1.55,state:'patrol',alert:0,stun:0,speed:42},
+ {x:1285,y:390,route:[[1285,390],[1480,370],[1640,300],[1600,430]],i:0,dir:0,state:'patrol',alert:0,stun:0,speed:48},
+ {x:1180,y:1050,route:[[1180,1050],[1420,1040],[1510,850],[1380,760]],i:0,dir:0,state:'patrol',alert:0,stun:0,speed:39}
+];
+const lamps=[[130,900],[330,700],[680,680],[970,750],[1230,620],[1570,390],[1550,270],[1060,190],[750,250],[380,1040],[1020,1110],[1510,880],[1640,200]];
+const crates=[[130,760],[602,735],[960,920],[1370,755],[1150,405],[300,1060],[820,790],[1540,620],[980,700],[570,650],[1200,1080]];
+const waterNoise=Array.from({length:95},(_,i)=>({x:(i*173)%1900,y:(i*97)%160,w:20+(i*19)%72}));
+const hash=(x,y)=>{let n=Math.sin(x*127.1+y*311.7)*43758.5453;return n-Math.floor(n)};
+function rectHit(x,y,r=12){return solid.some(b=>x+r>b.x&&x-r<b.x+b.w&&y+r>b.y&&y-r<b.y+b.h)}
+function circleRect(cx,cy,r,b){const x=Math.max(b.x,Math.min(cx,b.x+b.w)),y=Math.max(b.y,Math.min(cy,b.y+b.h));return (cx-x)**2+(cy-y)**2<r*r}
+function visible(a,b){const dx=b.x-a.x,dy=b.y-a.y,n=Math.ceil(Math.hypot(dx,dy)/18);for(let i=1;i<n;i++){let x=a.x+dx*i/n,y=a.y+dy*i/n;if(solid.some(r=>x>r.x&&x<r.x+r.w&&y>r.y&&y<r.y+r.h))return false;}return true}
+function startGame(){if(won||gameOver)reset();running=true;ui.modal.classList.add('hidden');last=performance.now();}
+ui.play.onclick=startGame;
+function reset(){player.x=135;player.y=1090;player.hp=100;player.blink=0;player.has=0;player.hidden=false;player.invuln=0;seals.forEach(s=>s.got=false);guards.forEach((g,i)=>{g.x=g.route[0][0];g.y=g.route[0][1];g.i=0;g.alert=0;g.stun=0;g.state='patrol'});won=false;gameOver=false;ui.seals.textContent='0 / 3';ui.health.style.width='100%';ui.objective.textContent='Find the three brass seals';ui.title.innerHTML='The Veil of <span>Greyhaven</span>';ui.kicker.textContent='A city holds its breath';ui.subtitle.textContent='A stealth tale in the drowned quarter';ui.story.textContent='The Lord Regent has sealed the old harbor. Three brass seals open the way into his watchtower — and the truth buried beneath it. Keep to the shadows. The city has a long memory.';ui.mission.innerHTML='<span class="seal">◈</span><span>Recover <em>three brass seals</em> and reach the lighthouse extraction. Stay unseen, or break the watch with your shadow-step.</span>';ui.play.textContent='Enter the quarter  →';ui.mission.style.display='flex'}
+function say(text){ui.toast.textContent=text;ui.toast.classList.add('show');toastTimer=2.2}
+function blink(){if(player.blink>0)return;const a=player.angle,dist=150;let tx=player.x+Math.cos(a)*dist,ty=player.y+Math.sin(a)*dist;tx=Math.max(24,Math.min(WW-24,tx));ty=Math.max(170,Math.min(WH-24,ty));for(let i=0;i<8;i++){let q=1-i*.1,x=player.x+(tx-player.x)*q,y=player.y+(ty-player.y)*q;if(!rectHit(x,y,11)){player.x=x;player.y=y;break}}player.blink=player.blinkMax;player.invuln=.45;say('SHADOW-STEP');}
+function interact(){for(const s of seals)if(!s.got&&Math.hypot(s.x-player.x,s.y-player.y)<45){s.got=true;player.has++;ui.seals.textContent=`${player.has} / 3`;say('BRASS SEAL RECOVERED');if(player.has===3){ui.objective.textContent='Reach the lighthouse';say('THE LIGHTHOUSE GATE IS OPEN');}return}if(Math.hypot(exit.x-player.x,exit.y-player.y)<70){if(player.has===3)finish(true);else say(`THE GATE NEEDS ${3-player.has} MORE SEAL${player.has===2?'':'S'}`);return}let nearest=guards.find(g=>g.stun<=0&&Math.hypot(g.x-player.x,g.y-player.y)<45);if(nearest){if(player.hidden||nearest.state!=='alert'){nearest.stun=12;nearest.state='stunned';nearest.alert=0;say('WATCHMAN SILENCED');}else{player.hp=Math.max(0,player.hp-13);nearest.stun=1.5;say('TOO CLOSE — BREAK AWAY');}}else say('NOTHING TO INTERACT WITH');}
+function whistle(){for(const g of guards){if(Math.hypot(g.x-player.x,g.y-player.y)<360&&g.stun<=0){g.state='investigate';g.alert=4;g.target={x:player.x,y:player.y};}}say('A LOW, HAUNTING CALL');}
+function finish(success){running=false;won=success;gameOver=!success;ui.modal.classList.remove('hidden');ui.kicker.textContent=success?'THE CITY WILL REMEMBER':'THE WATCH HAS FOUND YOU';ui.title.innerHTML=success?'A Quiet <span>Reckoning</span>':'Lost to the <span>Fog</span>';ui.subtitle.textContent=success?'Greyhaven wakes to a different dawn.':'The shadows close around you.';ui.story.textContent=success?'You slipped past the watch and carried the truth out with you. Somewhere beyond the harbor, the first bell rings.':'Your strength is spent. The harbor watch drags you into the fog. There is always another way through.';ui.mission.style.display='none';ui.play.textContent='Play again  →';}

