function finish(success){running=false;won=success;gameOver=!success;ui.modal.classList.remove('hidden');ui.kicker.textContent=success?'THE CITY WILL REMEMBER':'THE WATCH HAS FOUND YOU';ui.title.innerHTML=success?'A Quiet <span>Reckoning</span>':'Lost to the <span>Fog</span>';ui.subtitle.textContent=success?'Greyhaven wakes to a different dawn.':'The shadows close around you.';ui.story.textContent=success?'You slipped past the watch and carried the truth out with you. Somewhere beyond the harbor, the first bell rings.':'Your strength is spent. The harbor watch drags you into the fog. There is always another way through.';ui.mission.style.display='none';ui.play.textContent='Play again  →';}
function world(){
 ctx.fillStyle='#41443b';ctx.fillRect(0,0,WW,WH);
 // worn stone paving, varied but orderly
 for(let y=165;y<WH;y+=38)for(let x=0;x<WW;x+=54){let h=hash(x,y);ctx.fillStyle=['#45483f','#40443c','#484a41','#3d433d'][Math.floor(h*4)];ctx.fillRect(x+(y%76?0:27),y,52,36);ctx.strokeStyle='#282f2d66';ctx.lineWidth=2;ctx.strokeRect(x+(y%76?0:27)+1,y+1,50,34);if(h>.83){ctx.strokeStyle='#b29a6e17';ctx.beginPath();ctx.moveTo(x+10,y+8);ctx.lineTo(x+20,y+12);ctx.lineTo(x+17,y+27);ctx.stroke()}}
 // canal
 let water=ctx.createLinearGradient(0,0,0,190);water.addColorStop(0,'#1c3539');water.addColorStop(1,'#294245');ctx.fillStyle=water;ctx.fillRect(0,0,WW,166);ctx.fillStyle='#8c8a7270';ctx.fillRect(0,158,WW,13);
 for(const a of waterNoise){ctx.strokeStyle='rgba(155,177,163,.10)';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(a.x,a.y+30);ctx.lineTo(a.x+a.w,a.y+30);ctx.stroke();ctx.fillStyle='#b5aa8577';ctx.fillRect(a.x+((a.y|0)%17),a.y+68,1,1)}
 // docks, bollards
 for(let x=85;x<WW;x+=310){ctx.fillStyle='#584936';ctx.fillRect(x,110,115,74);ctx.fillStyle='#806748';ctx.fillRect(x+5,116,105,56);for(let xx=x+8;xx<x+115;xx+=28){ctx.fillStyle='#322e27';ctx.fillRect(xx,160,6,30)}}
 // drainage lanes and paving paths
 ctx.fillStyle='#353b36';ctx.fillRect(0,625,WW,67);ctx.fillRect(0,1000,WW,60);ctx.fillRect(475,170,64,WH-170);ctx.fillRect(1160,170,64,WH-170);ctx.fillRect(1555,170,58,WH-170);
 ctx.strokeStyle='#827b6750';ctx.lineWidth=2;ctx.setLineDash([12,18]);for(const y of [659,1030]){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(WW,y);ctx.stroke()}ctx.setLineDash([]);
 // little drains and manholes
 for(let x=35;x<WW;x+=145){ctx.fillStyle='#252d2b';ctx.fillRect(x,648,18,3);ctx.fillRect(x,1020,18,3)}
 // building footprints, masonry, peaked roof details
 for(let i=0;i<buildings.length;i++){let b=buildings[i];ctx.fillStyle='#212a28';ctx.fillRect(b.x-11,b.y-7,b.w+22,b.h+22);ctx.fillStyle='#292f2c';ctx.fillRect(b.x-6,b.y-4,b.w+12,b.h+11);ctx.fillStyle=b.roof;ctx.fillRect(b.x,b.y,b.w,b.h);ctx.strokeStyle='#77736177';ctx.lineWidth=3;ctx.strokeRect(b.x+5,b.y+5,b.w-10,b.h-10);ctx.fillStyle='#4c5048';ctx.fillRect(b.x+13,b.y+14,b.w-26,15);
  // roof seams and skylights
  ctx.strokeStyle='#232b29aa';ctx.lineWidth=4;for(let xx=b.x+38;xx<b.x+b.w-20;xx+=55){ctx.beginPath();ctx.moveTo(xx,b.y+28);ctx.lineTo(xx,b.y+b.h-15);ctx.stroke()}
  for(let xx=b.x+28;xx<b.x+b.w-32;xx+=82){ctx.fillStyle='#202927';ctx.fillRect(xx,b.y+43,31,20);ctx.fillStyle='#a18b5d77';ctx.fillRect(xx+4,b.y+47,23,11);ctx.fillStyle='#202927';ctx.fillRect(xx,b.y+b.h-42,31,20);ctx.fillStyle='#b6905666';ctx.fillRect(xx+4,b.y+b.h-38,23,11)}
  ctx.fillStyle='#6c6552';ctx.fillRect(b.x+b.w*.44,b.y+b.h-8,43,9);ctx.fillStyle='#242c29';ctx.fillRect(b.x+b.w*.44+5,b.y+b.h-8,33,8);
  ctx.fillStyle='#9b8c6a';ctx.font='9px Cinzel,serif';ctx.textAlign='center';ctx.fillText(b.name,b.x+b.w/2,b.y+31);
 }
 // stacks of crates/barrels as cover
 for(let i=0;i<crates.length;i++){let [x,y]=crates[i];if(i%3===0){ctx.fillStyle='#20262488';ctx.beginPath();ctx.ellipse(x,y+15,19,10,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#62513a';ctx.fillRect(x-14,y-7,28,21);ctx.fillStyle='#806746';ctx.fillRect(x-12,y-8,24,4);ctx.strokeStyle='#392f24';ctx.lineWidth=2;ctx.strokeRect(x-14,y-7,28,21);ctx.beginPath();ctx.moveTo(x-7,y-6);ctx.lineTo(x-7,y+13);ctx.moveTo(x+7,y-6);ctx.lineTo(x+7,y+13);ctx.stroke()}else{ctx.fillStyle='#252b28';ctx.fillRect(x-18,y-13,36,29);ctx.fillStyle='#6a5437';ctx.fillRect(x-16,y-16,32,28);ctx.strokeStyle='#3a3429';ctx.lineWidth=2;ctx.strokeRect(x-16,y-16,32,28);for(let k=-8;k<12;k+=10){ctx.beginPath();ctx.moveTo(x+k,y-15);ctx.lineTo(x+k,y+11);ctx.stroke()}}}
 // lantern light pools and iron posts
 for(const [x,y] of lamps){let glow=ctx.createRadialGradient(x,y,5,x,y,100);glow.addColorStop(0,'rgba(215,166,91,.15)');glow.addColorStop(1,'rgba(215,166,91,0)');ctx.fillStyle=glow;ctx.fillRect(x-100,y-100,200,200);ctx.fillStyle='#252a26';ctx.fillRect(x-2,y-14,4,22);ctx.fillStyle='#796446';ctx.fillRect(x-6,y-19,12,8);ctx.fillStyle='#e7c783';ctx.beginPath();ctx.arc(x,y-15,2.4,0,Math.PI*2);ctx.fill();}
 // lighthouse and extraction arch
 ctx.fillStyle='#242b29';ctx.fillRect(exit.x-29,exit.y-42,58,82);ctx.fillStyle='#605945';ctx.fillRect(exit.x-23,exit.y-38,46,74);ctx.fillStyle='#303633';ctx.beginPath();ctx.moveTo(exit.x-28,exit.y-38);ctx.lineTo(exit.x,exit.y-62);ctx.lineTo(exit.x+28,exit.y-38);ctx.fill();ctx.fillStyle='#e1bb73';ctx.fillRect(exit.x-4,exit.y-10,8,22);ctx.fillStyle='#f0d59a';ctx.beginPath();ctx.arc(exit.x,exit.y-50,3,0,Math.PI*2);ctx.fill();
}
function drawSeal(s){if(s.got)return;let p=1+Math.sin(time*2.7+s.x)*.15;let g=ctx.createRadialGradient(s.x,s.y,2,s.x,s.y,55*p);g.addColorStop(0,'rgba(229,183,105,.28)');g.addColorStop(1,'rgba(229,183,105,0)');ctx.fillStyle=g;ctx.fillRect(s.x-60,s.y-60,120,120);ctx.save();ctx.translate(s.x,s.y);ctx.rotate(time*.45);ctx.fillStyle='#c89c55';ctx.strokeStyle='#f2d792';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(0,-12);ctx.lineTo(9,0);ctx.lineTo(0,12);ctx.lineTo(-9,0);ctx.closePath();ctx.fill();ctx.stroke();ctx.fillStyle='#594525';ctx.beginPath();ctx.arc(0,0,3,0,Math.PI*2);ctx.fill();ctx.restore();}

